// RedLetterArtifact.swift
// Bundled Jesus-speech spans for a version whose own data
// carries no speaker markup (REQ-RL-4): the ChiUns module.
// Spans are character ranges in each verse's text exactly as
// the reader renders it. The table is built purely from
// published modules — it does not rely on any private version.
//
// Provenance: extracted Nov 4-5, 2026 from the NASB1995 module's
// publisher red-letter markup as the primary ground truth, with
// the KJV module's markup filling verses NASB left unattributed,
// and every span audited against ChiUns's own quotation
// delimiters (「」). The audit is strict: an attribution it
// could not make with confidence is left unpainted. Rebuilt
// Nov 6, 2026 with the offline reader anchored to the module's
// own chapter markers: a fixed heading model had undercounted
// extra entries in ChiUns's stream and shifted its Jude +
// Revelation reads by one to two verses.
// A module's own markup always takes precedence over this table.

import Foundation

public enum RedLetterArtifact {
    /// Jesus-speech spans for one verse, or [] when the artifact
    /// does not cover the version or the verse.
    public static func spans(versionID: String, book: String,
                             chapter: Int, verse: Int) -> [(start: Int, end: Int)] {
        chapterSpans(versionID: versionID, book: book, chapter: chapter)[verse] ?? []
    }

    /// All covered verses of one chapter, keyed by verse number.
    public static func chapterSpans(versionID: String, book: String,
                                    chapter: Int) -> [Int: [(start: Int, end: Int)]] {
        guard let section = table[versionID.lowercased()] else { return [:] }
        let prefix = "\(book).\(chapter)."
        var out = [Int: [(start: Int, end: Int)]]()
        for (key, raw) in section where key.hasPrefix(prefix) {
            guard let verse = Int(key.dropFirst(prefix.count)) else { continue }
            out[verse] = raw.map { (start: $0[0], end: $0[1]) }
        }
        return out
    }

    /// version key -> "Book.Chapter.Verse" -> [[start, end], ...]
    private static let table: [String: [String: [[Int]]]] = {
        guard let data = json.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data),
              let table = object as? [String: [String: [[Int]]]]
        else { return [:] }
        return table
    }()

